 }

+#[test_case::test_case(2; "one_child_uses_all_child_capacity")]
+#[test_case::test_case(4; "three_children_use_all_child_capacity")]
+#[tokio::test]
+async fn root_reload_message_preserves_full_child_capacity(max_threads: usize) {
+    let (home, mut config) = test_config().await;
+    config.features.enable(Feature::MultiAgentV2).unwrap();
+    config.features.enable(Feature::Sqlite).unwrap();
+    config.multi_agent_v2.max_concurrent_threads_per_session = max_threads;
+    let harness = AgentControlHarness::new_with_config(home, config).await;
+    let root = harness
+        .manager
+        .start_thread(StartThreadOptions::new(harness.config.clone()))
+        .await
+        .expect("start root");
+    let root_id = root.thread_id;
+    let control = root
+        .thread
+        .session
+        .services
+        .local_agent_runtime
+        .control(root.thread.session.session_id());
+    let mut children = Vec::new();
+    let mut pins = Vec::new();
+    for index in 0..max_threads - 1 {
+        let child = spawn_v2_reload_test_child(
+            &control,
+            harness.config.clone(),
+            &root.thread,
+            &format!("worker_{index}"),
+        )
+        .await;
+        let thread = harness.manager.get_thread(child.thread_id).await.unwrap();
+        // Keep all children resident, as with active message delivery. Do not
+        // let a successful root reload hide an eviction of a child worker.
+        pins.push(Arc::clone(&thread.residency_gate).read_owned().await);
+        persist_thread_for_tree_resume(&thread, "child persisted").await;
+        children.push((child.thread_id, thread));
+    }
+    persist_thread_for_tree_resume(&root.thread, "root persisted").await;
+    root.thread.shutdown_and_wait().await.unwrap();
+    assert!(harness.manager.remove_thread(&root_id).await.is_some());
+    assert_thread_not_loaded(&harness.manager, root_id).await;
+    drop(root);
+
+    let (sender_id, sender) = &children[0];
+    let turn = sender.session.new_default_turn().await;
+    sender
+        .session
+        .services
+        .agent_control
+        .send(crate::SendRequest {
+            caller: *sender_id,
+            target: crate::AgentTarget::Id(root_id),
+            resume_config: crate::agent::child_config::build_agent_resume_config(&turn).unwrap(),
+            input: crate::AgentInput::Message {
+                message: AgentMessage::Plaintext("result for unloaded root".to_string()),
+                mode: MessageDeliveryMode::QueueOnly,
+            },
+            start_options: TurnStartOptions {
+                root_turn_id: turn.turn_metadata_state.root_turn_id(),
+                turn_trigger: turn.turn_metadata_state.current_turn_trigger(),
+                cyber_access_program: turn.cyber_access_program,
+                ..Default::default()
+            },
+        })
+        .await
+        .expect("root reload must not require a child residency slot");
+    let reloaded = harness.manager.get_thread(root_id).await.unwrap();
+    timeout(Duration::from_secs(5), async {
+        while !reloaded
+            .session
+            .input_queue
+            .has_pending_input(&reloaded.session.active_turn)
+            .await
+        {
+            sleep(Duration::from_millis(10)).await;
+        }
+    })
+    .await
+    .expect("the child message must reach the reloaded root");
+    assert!(reloaded.session.active_turn.lock().await.is_none());
+    for (id, original) in &children {
+        let loaded = harness.manager.get_thread(*id).await.unwrap();
+        assert!(Arc::ptr_eq(original, &loaded), "all child workers must survive");
+    }
+    drop(pins);
+}
